import{_ as n,o as r,c as s,a3 as i}from"./chunks/framework.z_KJ15Ep.js";const a="/bilder/suchen-gruppenprozesse/gruppenprozesse-sprachenfolge-ermitteln.png",t="/bilder/suchen-gruppenprozesse/gruppenprozesse-sprachenfolge-ermitteln-eintraege-ueberschreiben.png",p="/bilder/suchen-gruppenprozesse/kataloge-unterrichtsfaecher-fremdsprache.png",b=JSON.parse('{"title":"Die Sprachenfolge aus Leistungsdaten ermitteln","description":"","frontmatter":{"title":"Die Sprachenfolge aus Leistungsdaten ermitteln","source_pageid":281,"source_revision":5339},"headers":[],"relativePath":"schild3/suchen-gruppenprozesse/sprachenfolge-aus-leistungsdaten-ermitteln-gruppenprozesse-allgemein.md","filePath":"schild3/suchen-gruppenprozesse/sprachenfolge-aus-leistungsdaten-ermitteln-gruppenprozesse-allgemein.md"}'),h={name:"schild3/suchen-gruppenprozesse/sprachenfolge-aus-leistungsdaten-ermitteln-gruppenprozesse-allgemein.md"};function d(l,e,o,g,c,u){return r(),s("div",null,[...e[0]||(e[0]=[i('<h1 id="die-sprachenfolge-aus-leistungsdaten-ermitteln" tabindex="-1">Die Sprachenfolge aus Leistungsdaten ermitteln <a class="header-anchor" href="#die-sprachenfolge-aus-leistungsdaten-ermitteln" aria-label="Permalink to &quot;Die Sprachenfolge aus Leistungsdaten ermitteln&quot;">​</a></h1><p>Ergänzen Sie Sprachenfolgen aus den vorhandenen Leistungsdaten. Entscheiden Sie vor dem Start, ob bereits erfasste Einträge überschrieben werden dürfen.</p><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-sprachenfolge-ermitteln.png"><img src="'+a+'" alt="Gruppenprozess zur automatischen Ermittlung der Sprachenfolge." loading="lazy"></a></p><p><em>Gruppenprozess zur automatischen Ermittlung der Sprachenfolge.</em></p><p>Der Gruppenprozess <strong>Sprachenfolgen aus Leistungsdaten ermitteln</strong> dient dazu, die Einträge in der Sprachenfolge unter <em>Schüler ➜ Laufbahninfo</em> zu vervollständigen.</p><p>Wird dieser Prozess ausgeführt, werden die Einträge auf Basis der Unterrichtsdaten für das jeweilige aktuelle Halbjahr aktualisiert.</p><p>Hat der Schüler oder die Schülerin inzwischen eine neue Fremdsprache in den Leistungsdaten, wird diese mit der passenden Reihenfolge und dem Beginn des Sprachenlernens in der Laufbahninfo neu eingetragen.</p><p><a href="/bilder/suchen-gruppenprozesse/gruppenprozesse-sprachenfolge-ermitteln-eintraege-ueberschreiben.png"><img src="'+t+'" alt="Sicherheitsabfrage, ob vorhandene Einträge überschrieben werden sollen." loading="lazy"></a></p><p><em>Sicherheitsabfrage, ob vorhandene Einträge überschrieben werden sollen.</em></p><p>Dabei fragt der Gruppenprozess, ob vorhandene Einträge überschrieben werden sollen.</p><p><a href="/bilder/suchen-gruppenprozesse/kataloge-unterrichtsfaecher-fremdsprache.png"><img src="'+p+'" alt="Bei den Unterrichtsfächern muss der der Haken bei gesetzt sein." loading="lazy"></a></p><p><em>Bei den Unterrichtsfächern muss der der Haken bei gesetzt sein.</em></p><p>Damit Unterrichtsfächer in die Sprachenfolge eingetragen werden können, müssen sie als <em>Fremdsprache</em> markiert sein.</p><p>Dazu muss unter <em>Kataloge ➜ Unterrichtsfächer ➜ Sonstige Einstellungen</em> der Haken bei <strong>Fremdsprache</strong> gesetzt sein.</p><h2 id="mit-uberschreiben-vorhandener-daten" tabindex="-1">Mit Überschreiben vorhandener Daten <a class="header-anchor" href="#mit-uberschreiben-vorhandener-daten" aria-label="Permalink to &quot;Mit Überschreiben vorhandener Daten&quot;">​</a></h2><p>Hierbei werden alle vorhandenen Einträge ignoriert und die Sprachenfolge so übernommen, wie sie in den Leistungsdaten vorhanden sind.</p><p>Dieses kann bei Schülerinnen und Schülern, die später auf die Schule gewechselt sind, problematisch sein. Kommt zum Beispiel ein Schüler oder eine Schülerin durch Umzug erst zur 8. Klasse an die Schule, sind in SchILD-NRW die Leistungsdaten der Klassen 5 - 7 nicht vorhanden.</p><p>Dieser Schüler würde dann in der Sprachenfolge zum Beispiel Franzöisch erst ab Klasse 8 vorliegen haben.</p><h2 id="ohne-uberschreiben-vorhandener-daten" tabindex="-1">Ohne Überschreiben vorhandener Daten <a class="header-anchor" href="#ohne-uberschreiben-vorhandener-daten" aria-label="Permalink to &quot;Ohne Überschreiben vorhandener Daten&quot;">​</a></h2><p>Mit dieser Option bleiben vorhandene Einträge erhalten. Der Prozess ergänzt nur fehlende Angaben.</p><p>So wird der Abschluss einer Fremdsprache mit dem richtigen Halbjahr eingetragen, wenn dort vorher keine Angabe war.</p><p>Fremdspracheneinträge, die nicht in den Leistungsdaten auftauchen, werden nicht verändert.</p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Sprachenfolge_aus_Leistungsdaten_ermitteln_(Gruppenprozesse_Allgemein)" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 5339.</p>',24)])])}const f=n(h,[["render",d]]);export{b as __pageData,f as default};
